import { Injectable } from '@angular/core';
import { CanActivate, ActivatedRouteSnapshot, RouterStateSnapshot, UrlTree, Router } from '@angular/router';
import { Observable } from 'rxjs';
import { GAccount } from '../../common/GAccount';
import { Urls } from '../../common/Urls';

@Injectable({
  providedIn: 'root'
})
export class TeacherGuard implements CanActivate {

  constructor(private router: Router) { }

  canActivate(
    next: ActivatedRouteSnapshot,
    state: RouterStateSnapshot): Observable<boolean | UrlTree> | Promise<boolean | UrlTree> | boolean | UrlTree {

    if (GAccount.IsTeacherActive()) {
      return true;
    } else if (!GAccount.IsTeacher() && GAccount.IsLoggedIn()) {
      this.router.navigateByUrl(Urls.AccessDeniedUrl);
      return false;
    } else if (!GAccount.IsTeacherActive() && GAccount.IsTeacher() && GAccount.IsLoggedIn()) {
      this.router.navigateByUrl(Urls.ActivatedAccessDeniedUrl);
      return false;
    } else {
      this.router.navigateByUrl(Urls.AccessDeniedUrl);
      return false;
    }
  }

}
