import { NgModule } from '@angular/core';
import { BrowserModule } from '@angular/platform-browser';
import { RouteReuseStrategy, UrlSerializer } from '@angular/router';

import { IonicModule, IonicRouteStrategy } from '@ionic/angular';

import { AppComponent } from './app.component';
import { AppRoutingModule } from './app-routing.module';
import { ServiceWorkerModule } from '@angular/service-worker';
import { environment } from '../environments/environment';
import { FormsModule } from '@angular/forms';
import { LoadingModule } from './view/components/common/loading/loading.module';
import { HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { ProductService } from './data/service/product/product.service';
import { CourseService } from './data/service/course/course.service';
import { ArticleService } from './data/service/article/article.service';
import { SliderService } from './data/service/site/Slider.service';
import { OrderService } from './data/service/order/order.service';
import { UserService } from './data/service/user/user.service';
import { AccountInterceptor } from './core/utility/account.interceptor';
import { AppAvailability } from '@awesome-cordova-plugins/app-availability/ngx';
import { StatusBar } from '@awesome-cordova-plugins/status-bar/ngx';
import { SplashScreen } from '@awesome-cordova-plugins/splash-screen/ngx';
import { Deeplinks } from '@awesome-cordova-plugins/deeplinks/ngx';
// import { GoogleAnalytics } from '@awesome-cordova-plugins/google-analytics/ngx';
import { Geolocation } from '@awesome-cordova-plugins/geolocation/ngx';
import { BLE } from '@awesome-cordova-plugins/ble/ngx';
import { TranslateModule } from '@ngx-translate/core';
import { LocaleUrlSerializer } from './core/i18n/locale-url-serializer';
import { SiteI18nModule } from './core/i18n/site-i18n.module';

@NgModule({
  declarations: [AppComponent],
  imports: [
    BrowserModule,
    IonicModule.forRoot(),
    AppRoutingModule,
    FormsModule,
    LoadingModule,
    HttpClientModule,
    TranslateModule.forRoot(),
    SiteI18nModule,
    ServiceWorkerModule.register('ngsw-worker.js', {
      enabled: environment.production,
      // Register the ServiceWorker as soon as the application is stable
      // or after 30 seconds (whichever comes first).
      registrationStrategy: 'registerWhenStable:30000'
    })],
  providers: [
    StatusBar,
    SplashScreen,
    {
      provide: RouteReuseStrategy,
      useClass: IonicRouteStrategy
    },
    { provide: UrlSerializer, useClass: LocaleUrlSerializer },
    ProductService,
    // GoogleAnalytics,
    CourseService,
    ArticleService,
    SliderService,
    Deeplinks,
    Geolocation,
    AppAvailability,
    OrderService,
    BLE,
    UserService,
    {
      provide: HTTP_INTERCEPTORS,
      useClass: AccountInterceptor,
      multi: true
    }
  ],
  bootstrap: [AppComponent],
})
export class AppModule { }
