import * as CryptoJS from 'crypto-js';
import { G } from './G';
import { environment } from 'src/environments/environment';

export class CryptographyHelper {

  private static privateKey = '@Nima#SecretKey$2k12';
  private static secret = 'oiwy#1Pwq';

  public static encrypt(plaintext: string): string {
    try {
      return CryptoJS.AES.encrypt(JSON.stringify(plaintext), this.privateKey).toString();
    } catch (e) {
      // console.log('encrypt failed');
    }
  }

  public static decrypt(cypher: string): string {
    try {
      const bytes = CryptoJS.AES.decrypt(cypher, this.privateKey);
      if (bytes.toString()) {
        return JSON.parse(bytes.toString(CryptoJS.enc.Utf8));
      }
      return cypher;
    } catch (e) {
      // console.log('decrypt failed');
    }
  }

  public static buildSecureLink(path: string): string {

    if (!environment.production) {

      G.UserIp = '2.147.192.83';
    }

    const videoUrl = new URL(path, window.location.origin);
    const baseUrl = videoUrl.origin;
    path = videoUrl.pathname;
    const expires = Math.floor(Date.now() / 1000) + 86400; //86400 = 1 Day
    const md5Input = `${expires}${path}${G.UserIp} ${this.secret}`;

    const md5Hash = CryptoJS.MD5(md5Input).toString(CryptoJS.enc.Latin1);
    let md5Base64 = CryptoJS.enc.Base64.stringify(CryptoJS.enc.Latin1.parse(md5Hash));

    md5Base64 = md5Base64.replace(/\+/g, '-').replace(/\//g, '_');
    md5Base64 = md5Base64.replace(/=/g, '');

    return `${baseUrl}${path}?md5=${md5Base64}&expires=${expires}`;
  }
}
