import { DOCUMENT } from '@angular/common';
import { Inject, Injectable } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import * as faTranslations from '../../../assets/i18n/fa.json';
import * as enTranslations from '../../../assets/i18n/en.json';

export type SiteLanguage = 'fa' | 'en' | 'ar' | 'tr' | 'ru';

// Publish a language only when its shared interface catalog is ready.
const publishedLanguages: SiteLanguage[] = ['fa', 'en'];
const languagePrefix = new RegExp(`^/(${publishedLanguages.join('|')})(?=/|[?#]|$)`, 'i');

export function stripLanguagePrefix(url: string): string {
  const clean = url.replace(languagePrefix, '');
  return clean.startsWith('/') ? clean : '/' + clean;
}

@Injectable({ providedIn: 'root' })
export class SiteLanguageService {
  private currentLanguage: SiteLanguage = 'fa';

  constructor(
    @Inject(DOCUMENT) private document: Document,
    private translate: TranslateService
  ) {
    // Bundle the published catalogs so the initial Persian page renders without a network request.
    this.translate.setTranslation('fa', faTranslations);
    this.translate.setTranslation('en', enTranslations);
    this.translate.addLangs(publishedLanguages);
    this.translate.setDefaultLang('fa');
    this.syncFromUrl(this.document.location.pathname);
  }

  get current(): SiteLanguage { return this.currentLanguage; }
  get direction(): 'rtl' | 'ltr' { return this.currentLanguage === 'fa' || this.currentLanguage === 'ar' ? 'rtl' : 'ltr'; }
  // Preserve the original Persian header: brand left, menu button right.
  get headerDirection(): 'rtl' | 'ltr' { return this.direction === 'rtl' ? 'ltr' : 'rtl'; }

  text(key: string, params?: Record<string, string | number>): string {
    return this.translate.instant(key, params);
  }

  // Keep legacy Persian URLs intact and preserve English across all routes.
  url(path: string, language: SiteLanguage = this.currentLanguage): string {
    const clean = stripLanguagePrefix(path);
    if (language === 'fa' || !publishedLanguages.includes(language)) { return clean; }
    return '/' + language + (clean === '/' ? '' : clean);
  }

  alternateUrl(language: SiteLanguage): string {
    const location = this.document.location;
    return this.url(location.pathname, language) + location.search + location.hash;
  }

  syncFromUrl(url: string): void {
    const match = languagePrefix.exec(url);
    const requested = match ? match[1].toLowerCase() as SiteLanguage : 'fa';
    const language = requested !== 'fa' && publishedLanguages.includes(requested)
      ? requested : 'fa';
    if (language === this.currentLanguage && this.translate.currentLang === language) { return; }
    this.currentLanguage = language;
    this.document.documentElement.lang = language;
    this.document.documentElement.dir = this.direction;
    this.translate.use(language);
  }
}
