import { Injectable } from '@angular/core';
import { CanActivate, ActivatedRouteSnapshot, RouterStateSnapshot, UrlTree, Router, NavigationEnd } from '@angular/router';
import { ToastController } from '@ionic/angular';
import { Observable } from 'rxjs';
import { filter } from 'rxjs/Operators';
import { GAccount } from '../../common/GAccount';
import { SharedIonic } from '../../common/SharedIonic';
import { Urls } from '../../common/Urls';

@Injectable({
  providedIn: 'root'
})
export class DeactiveAuthGuard implements CanActivate {

  pervRoute = 'null';

  constructor(private router: Router, public toastController: ToastController) {

    router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .subscribe((event: NavigationEnd) => {
        this.pervRoute = event.url;
      });
  }

  canActivate(
    next: ActivatedRouteSnapshot,
    state: RouterStateSnapshot): Observable<boolean | UrlTree> | Promise<boolean | UrlTree> | boolean | UrlTree {

    if (GAccount.IsLoggedIn()) {
      SharedIonic.toast(this.toastController, 'قبلا وارد شده اید');
      if (this.pervRoute === 'null') {
        this.router.navigateByUrl(Urls.HomeUrl);
      }
      return false;
    } else {
      return true;
    }
  }
}
