import { Injectable } from '@angular/core';
import { DefaultUrlSerializer, UrlTree } from '@angular/router';
import { SiteLanguageService, stripLanguagePrefix } from './site-language.service';

@Injectable()
export class LocaleUrlSerializer extends DefaultUrlSerializer {
  constructor(private language: SiteLanguageService) { super(); }

  parse(url: string): UrlTree {
    this.language.syncFromUrl(url);
    return super.parse(stripLanguagePrefix(url));
  }

  serialize(tree: UrlTree): string {
    return this.language.url(super.serialize(tree));
  }
}
