  clearCaches() {

    if ('caches' in window) {
      caches.keys()
        .then((keyList) => Promise.all(keyList.map((key) => caches.delete(key))));
    }

    if (window.navigator && navigator.serviceWorker) {
      navigator.serviceWorker.getRegistrations()
        .then((registrations) => {
          for (const registration of registrations) {
            registration.unregister();
          }
        });
    }

    setTimeout(() => {

      location.reload();
    }, 1000);
  }

  isHybrid(): boolean {

    if (this.platform.is('hybrid')) {
      return true;
    } else {
      return false;
    }
  }

  IsAndroidBrowser(): boolean {

    if (this.platform.is('android') && this.platform.is('mobileweb') && !this.platform.is('hybrid')) {

      return true;
    } else {
      return false;
    }
  }

  clearCacheStorage(): Promise<Promise<boolean>[][]> {
    return caches.keys().then(cacheKeys =>
      Promise.all(
        cacheKeys.map(cacheKey => {
          const ngswRegex = /^(ngsw).*/;
          if (ngswRegex.test(cacheKey)) {
            return caches
              .open(cacheKey)
              .then(cache => cache.keys().then(requests => requests.map(req => cache.delete(req))));
          }
        })
      )
    );
  }

