  CheckTheme() {

    let found = false;

    for (let i = 0; i < localStorage.length; i++) {
      if (localStorage.key(i) === 'theme') {
        found = true;
        if (localStorage.getItem('theme') === 'dark') {
          this.dark = true;
        } else {
          this.dark = false;
        }
      }
    }

    if (!found) {
      this.dark = false;
    }

    this.document.body.classList.toggle('dark-theme', this.dark);
    G.darkTheme = this.dark;
    G.setCurrentMode(G.darkTheme);
  }

  CheckVoice() {

    let found = false;

    for (let i = 0; i < localStorage.length; i++) {
      if (localStorage.key(i) === 'voice') {
        found = true;
        if (localStorage.getItem('voice') === '1') {
          this.voice = true;
        } else {
          this.voice = false;
        }
      }
    }

    if (!found) {
      this.voice = false;
    }

    G.voice = this.voice;
    G.setCurrentVoice(G.voice);
  }

  ThemeChanged(dark: boolean) {
    this.dark = dark;
    this.document.body.classList.toggle('dark-theme', dark);
    localStorage.setItem('theme', dark ? 'dark' : 'light');
    G.darkTheme = dark;
    G.setCurrentMode(G.darkTheme);
  }

  VoiceChanged() {

    for (let i = 0; i < localStorage.length; i++) {
      if (localStorage.key(i) === 'voice') {
        localStorage.removeItem('voice');
      }
    }

    if (!this.voice) {
      localStorage.setItem('voice', '1');
    } else {
      localStorage.setItem('voice', '0');
    }

    G.voice = !this.voice;
    G.setCurrentVoice(G.voice);
  }

  async SignOut() {
    const alert = await this.alertController.create({
      // header: 'Confirm!',
      message: 'آیا برای خروج مطمئن هستید؟',
      cssClass: 'exit-alert',
      buttons: [{
        text: 'لغو',
        role: 'cancel',
        handler: (blah) => { }
      }, {
        text: 'خروج',
        handler: () => {
          this.onSignOut();
        }
      }]
    });

    await alert.present();
  }

  private signingOut = false;

  onSignOut(): void {
    if (this.signingOut) { return; }
    const token = GAccount.TokenDecryptValue;
    const complete = () => {
      this.signingOut = false;
      if (GAccount.TokenDecryptValue && GAccount.TokenDecryptValue !== token) { return; }
      GAccount.SignOut();
      this.router.navigateByUrl(this.language.url(Urls.AccountUrl));
      SharedIonic.dismissLoading(this.loadingController);
    };
    if (!GAccount.IsLoggedIn()) { complete(); return; }

    this.signingOut = true;
    this.accountService.Logout().subscribe({
      next: complete,
      error: err => {
        if (err.status === 401 && err.error?.code === 'invalid_session') {
          complete();
        } else {
          this.signingOut = false;
          SharedIonic.toast(this.toastController, this.language.text('account.logoutFailed'));
        }
      }
    });
  }

  @HostListener('window:storage', ['$event'])
  onSessionStorageChange(event: StorageEvent): void {
    if (event.storageArea !== localStorage) { return; }
    const token = GAccount.TokenDecryptValue;
    GAccount.CheckUser();
    if (token && !GAccount.IsLoggedIn()) {
      this.router.navigateByUrl(this.language.url(Urls.AccountUrl));
    }
  }

  IsLoggedin(): boolean {
    return GAccount.IsLoggedIn();
  }

  IsAdmin(): boolean {
    return GAccount.IsAdmin();
  }

  IsUser(): boolean {
    return GAccount.IsLoggedIn() && !GAccount.IsAdmin();
  }

  IsSuperAdmin(): boolean {
    return GAccount.IsSuperAdmin();
  }

  CanViewRestrictedPages(): boolean {
    return GAccount.IsAdminActive() || GAccount.IsSuperAdminActive();
  }

  IsSeller(): boolean {
    return GAccount.IsSeller();
  }

  IsTeacher(): boolean {
    return GAccount.IsTeacher();
  }

  IsInstagramAdmin(): boolean {
    return GAccount.IsInstagramAdmin();
  }
