
import { ToastController, LoadingController, AlertController } from '@ionic/angular';

export class SharedIonic {

    public static isLoading = false;

    constructor() { }

    // Alert

    public static async alert(alertController: AlertController, title: string, subTitle: string, content: string) {
        const alert = await alertController.create({
            cssClass: 'main-alert',
            header: title,
            subHeader: subTitle,
            message: content,
            buttons: ['OK']
        });

        await alert.present();
    }

    // Loading

    public static async loading(loadingController: LoadingController) {

        try {
            if (this.isLoading) {
                return;
            }

            this.isLoading = true;

            return await loadingController.create({
                // spinner: null,
                duration: 500000,
                message: 'لطفا صبر کنید',
                translucent: true,
                cssClass: 'main-loading',
                backdropDismiss: false
            }).then(a => {
                a.present().then(() => {
                    if (!this.isLoading) {
                        a.dismiss().then(() => { });
                    }
                });
            });
        } catch (error) {

        }
    }

    public static async dismissLoading(loadingController: LoadingController) {

        try {
            if (!this.isLoading) {
                return;
            }
            this.isLoading = false;
            return await loadingController.dismiss().then(() => { });
        } catch (error) {

        }
    }

    // Toast

    public static async toast(toastController: ToastController, msg: string) {

        try {
            const toast = await toastController.create({
                message: msg,
                cssClass: 'main-toast',
                duration: 3000
            });
            toast.present();
        } catch (error) {

        }
    }

    public static async successToast(toastController: ToastController) {

        try {
            const toast = await toastController.create({
                message: 'با موفقیت انجام شد',
                cssClass: 'main-success-toast',
                duration: 3000
            });
            toast.present();
        } catch (error) {

        }
    }

    public static async unSuccessToast(toastController: ToastController) {

        try {
            const toast = await toastController.create({
                message: 'انجام نشد',
                cssClass: 'main-unsuccess-toast',
                duration: 3000
            });
            toast.present();
        } catch (error) {

        }
    }
}
