import { Injectable } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Subject, throwError, Observable } from 'rxjs';
import { MembershipSubjectModel, IMembershipSubjectModel } from '../../model/common/MembershipSubjectModel';
import { IRegisterModel } from '../../model/account/RegisterModel';
import { catchError, retry, timeout } from 'rxjs/Operators';
import { ILoginModel } from '../../model/account/LoginModel';
import { CryptographyHelper } from '../../../core/common/CryptographyHelper';
import { GAccount } from '../../../core/common/GAccount';
import { IForgetPasswordModel } from '../../model/account/ForgetPasswordModel';
import { IAccountResponseResult } from '../../model/account/IAccountResponseResult';
import { ISellerRegisterModel } from '../../model/account/SellerRegisterModel';
import { ITeacherRegisterModel } from '../../model/account/TeacherRegisterModel';
import { IAdminRegisterModel } from '../../model/account/AdminRegisterModel';
import { IChangePasswordModel } from '../../model/account/ChangePasswordModel';
import { IResetPasswordModel, IConfirmEmailModel, IConfirmPhoneModel } from '../../model/account/ResetPasswordModel';
import { IResponseResult } from '../../model/common/IResponseResult';
import { IAddRemoveRoleModel } from '../../model/account/BaseRegisterModel';

@Injectable({
  providedIn: 'root'
})
export class AccountService {

  constructor(private http: HttpClient) { }

  public static ErrorState = 0;
  public static ErrorMessage = '';

  // Urls
  private loginUrl = '/api/Account/Login';
  private logoutUrl = '/api/Account/Logout';
  private RegisterUrl = '/api/account/Register';
  private ExternalRegisterUrl = '/api/account/ExternalRegister';
  private SelerRegisterUrl = '/api/account/SellerRegister';
  private TeacherRegisterUrl = '/api/account/TeacherRegister';
  private AdminRegisterUrl = '/api/account/AdminRegister';
  private ForgetPasswordUrl = '/api/account/ForgetPassword';
  private ChangePasswordUrl = '/api/account/ChangePassword';
  private ResetPasswordUrl = '/api/account/ResetPassword';
  private ConfirmEmailUrl = '/api/account/ConfirmEmail';
  private ConfirmPhoneUrl = '/api/account/ConfirmPhone';
  private ActiveAdminUserByEmailUrl = '/api/account/ActiveAdminUserByEmail';
  private BlockAdminUserByEmailUrl = '/api/account/BlockAdminUserByEmail';
  private DeActiveLockoutUrl = '/api/account/DeActiveLockout';
  private ActiveLockoutUrl = '/api/account/ActiveLockout';
  private AdminForceDeActiveUrl = '/api/account/AdminForceDeActive';
  private AdminForceActiveUrl = '/api/account/AdminForceActive';


  public static TokenRolesInit(res: IAccountResponseResult, email: string): void {

    const response: IAccountResponseResult = res;
    let rolesKey: string;
    let rolesValue: string;

    if (email == null) {

      if (GAccount.IsLoggedIn()) {
        GAccount.SignOut2();
      }
    } else {
      if (GAccount.IsLoggedIn()) {
        GAccount.SignOut();
      }

      GAccount.UserEmail = email;
      localStorage.setItem('Email', email);
    }

    GAccount.TokenKey = CryptographyHelper.encrypt(GAccount.TokenDecryptKey);
    GAccount.TokenValue = CryptographyHelper.encrypt(res.token);
    localStorage.setItem(GAccount.TokenKey, GAccount.TokenValue);

    GAccount.CurrrentUserRoles = response.roles;

    if (response.roles[GAccount.BuyerType] != null) {

      rolesKey = CryptographyHelper.encrypt(GAccount.BuyerType);

      if (response.roles[GAccount.BuyerType] === true) {
        rolesValue = CryptographyHelper.encrypt(GAccount.ActiveRole);
      } else {
        rolesValue = CryptographyHelper.encrypt(GAccount.DeActiveRole);
      }
      localStorage.setItem(rolesKey, rolesValue);
    }

    if (response.roles[GAccount.SellerType] != null) {

      rolesKey = CryptographyHelper.encrypt(GAccount.SellerType);

      if (response.roles[GAccount.SellerType] === true) {
        rolesValue = CryptographyHelper.encrypt(GAccount.ActiveRole);
      } else {
        rolesValue = CryptographyHelper.encrypt(GAccount.DeActiveRole);
      }
      localStorage.setItem(rolesKey, rolesValue);
    }

    if (response.roles[GAccount.TeacherType] != null) {
      rolesKey = CryptographyHelper.encrypt(GAccount.TeacherType);

      if (response.roles[GAccount.TeacherType] === true) {
        rolesValue = CryptographyHelper.encrypt(GAccount.ActiveRole);
      } else {
        rolesValue = CryptographyHelper.encrypt(GAccount.DeActiveRole);
      }
      localStorage.setItem(rolesKey, rolesValue);
    }

    if (response.roles[GAccount.AdminType] != null) {
      rolesKey = CryptographyHelper.encrypt(GAccount.AdminType);

      if (response.roles[GAccount.AdminType] === true) {
        rolesValue = CryptographyHelper.encrypt(GAccount.ActiveRole);
      } else {
        rolesValue = CryptographyHelper.encrypt(GAccount.DeActiveRole);
      }
      localStorage.setItem(rolesKey, rolesValue);
    }

    if (response.roles[GAccount.SuperAdminType] != null) {
      rolesKey = CryptographyHelper.encrypt(GAccount.SuperAdminType);

      if (response.roles[GAccount.SuperAdminType] === true) {
        rolesValue = CryptographyHelper.encrypt(GAccount.ActiveRole);
      } else {
        rolesValue = CryptographyHelper.encrypt(GAccount.DeActiveRole);
      }
      localStorage.setItem(rolesKey, rolesValue);
    }

    // Fake Item to run mad hackers!
    localStorage.setItem(CryptographyHelper.encrypt(GAccount.FakeDecryptKey), CryptographyHelper.encrypt(GAccount.FakeDecryptValue));

    GAccount.CheckUser();
  }

  public static TokenRolesInit2(res: IAccountResponseResult): void {

    const response: IAccountResponseResult = res;
    let rolesKey: string;
    let rolesValue: string;

    if (GAccount.IsLoggedIn()) {
      GAccount.SignOut();
    }

    GAccount.TokenKey = CryptographyHelper.encrypt(GAccount.TokenDecryptKey);
    GAccount.TokenValue = CryptographyHelper.encrypt(res.token);
    localStorage.setItem(GAccount.TokenKey, GAccount.TokenValue);

    GAccount.CurrrentUserRoles = response.roles;

    if (response.roles.has(GAccount.BuyerType)) {

      rolesKey = CryptographyHelper.encrypt(GAccount.BuyerType);

      if (response.roles.get(GAccount.BuyerType) === true) {
        rolesValue = CryptographyHelper.encrypt(GAccount.ActiveRole);
      } else {
        rolesValue = CryptographyHelper.encrypt(GAccount.DeActiveRole);
      }
      localStorage.setItem(rolesKey, rolesValue);
    }

    if (response.roles.has(GAccount.SellerType)) {

      rolesKey = CryptographyHelper.encrypt(GAccount.SellerType);

      if (response.roles.get(GAccount.SellerType) === true) {
        rolesValue = CryptographyHelper.encrypt(GAccount.ActiveRole);
      } else {
        rolesValue = CryptographyHelper.encrypt(GAccount.DeActiveRole);
      }
      localStorage.setItem(rolesKey, rolesValue);
    }

    if (response.roles.has(GAccount.TeacherType)) {
      rolesKey = CryptographyHelper.encrypt(GAccount.TeacherType);

      if (response.roles.get(GAccount.TeacherType) === true) {
        rolesValue = CryptographyHelper.encrypt(GAccount.ActiveRole);
      } else {
        rolesValue = CryptographyHelper.encrypt(GAccount.DeActiveRole);
      }
      localStorage.setItem(rolesKey, rolesValue);
    }

    if (response.roles.has(GAccount.AdminType)) {
      rolesKey = CryptographyHelper.encrypt(GAccount.AdminType);

      if (response.roles.get(GAccount.AdminType) === true) {
        rolesValue = CryptographyHelper.encrypt(GAccount.ActiveRole);
      } else {
        rolesValue = CryptographyHelper.encrypt(GAccount.DeActiveRole);
      }
      localStorage.setItem(rolesKey, rolesValue);
    }

    if (response.roles.has(GAccount.SuperAdminType)) {
      rolesKey = CryptographyHelper.encrypt(GAccount.SuperAdminType);

      if (response.roles.get(GAccount.SuperAdminType) === true) {
        rolesValue = CryptographyHelper.encrypt(GAccount.ActiveRole);
      } else {
        rolesValue = CryptographyHelper.encrypt(GAccount.DeActiveRole);
      }
      localStorage.setItem(rolesKey, rolesValue);
    }

    // Fake Item to run mad hackers!
    localStorage.setItem(CryptographyHelper.encrypt(GAccount.FakeDecryptKey), CryptographyHelper.encrypt(GAccount.FakeDecryptValue));

    GAccount.CheckUser();
  }

  Register(model: IRegisterModel): Observable<IAccountResponseResult> {

    return this.http
      .post<IAccountResponseResult>(this.RegisterUrl, model, { responseType: 'json' })
      .pipe(catchError(this.showError));
  }

  ExternalRegister(model: IRegisterModel): Observable<IAccountResponseResult> {

    return this.http
      .post<IAccountResponseResult>(this.ExternalRegisterUrl, model, { responseType: 'json', withCredentials: true })
      .pipe(timeout(30000), catchError(this.showError));
  }

  SellerRegister(model: ISellerRegisterModel): Observable<IAccountResponseResult> {

    return this.http
      .post<IAccountResponseResult>(this.SelerRegisterUrl, model, { responseType: 'json' })
      .pipe(catchError(this.showError));
  }

  TeacherRegister(model: ITeacherRegisterModel): Observable<IAccountResponseResult> {

    return this.http
      .post<IAccountResponseResult>(this.TeacherRegisterUrl, model, { responseType: 'json' })
      .pipe(catchError(this.showError));
  }

  AdminRegister(model: IAdminRegisterModel): Observable<IAccountResponseResult> {

    return this.http
      .post<IAccountResponseResult>(this.AdminRegisterUrl, model, { responseType: 'json' })
      .pipe(catchError(this.showError));
  }

  Login(model: ILoginModel): Observable<IAccountResponseResult> {

    return this.http
      .post<IAccountResponseResult>(this.loginUrl, model, { responseType: 'json' })
      .pipe(catchError(this.showError));
  }

  ValidateSession(): Observable<void> {
    return this.http.get<void>('/api/Account/Session');
  }

  Logout(): Observable<void> {

    return this.http
      .post<void>(this.logoutUrl, null, { responseType: 'json' }).pipe(timeout(15000));
  }

  ForgetPassword(model: IForgetPasswordModel) {

    return this.http
      .post(this.ForgetPasswordUrl, model, { responseType: 'json' })
      .pipe(catchError(this.showError));
  }

  ResetPassword(model: IResetPasswordModel) {

    return this.http
      .post(this.ResetPasswordUrl, model, { responseType: 'json' })
      .pipe(catchError(this.showError));
  }

  ConfirmEmail(model: IConfirmEmailModel) {

    return this.http
      .post(this.ConfirmEmailUrl, model, { responseType: 'json' })
      .pipe(catchError(this.showError));
  }

  ConfirmPhone(model: IConfirmPhoneModel) {

    return this.http
      .post(this.ConfirmPhoneUrl, model, { responseType: 'json' })
      .pipe(catchError(this.showError));
  }

  ChangePassword(model: IChangePasswordModel): Observable<IAccountResponseResult> {

    return this.http
      .post<IAccountResponseResult>(this.ChangePasswordUrl, model, { responseType: 'json' })
      .pipe(catchError(this.showError));
  }

  ActiveAdminUserByEmail(email: string): Observable<IResponseResult<unknown>> {

    return this.http
      .post<IResponseResult<unknown>>(this.ActiveAdminUserByEmailUrl + '?email=' + email, { responseType: 'json' });
  }

  BlockAdminUserByEmail(email: string): Observable<IResponseResult<unknown>> {

    return this.http
      .post<IResponseResult<unknown>>(this.BlockAdminUserByEmailUrl + '?email=' + email, { responseType: 'json' });
  }

  ActiveLockout(model: IForgetPasswordModel): Observable<IResponseResult<unknown>> {

    return this.http
      .post<IResponseResult<unknown>>(this.ActiveLockoutUrl, model, { responseType: 'json' });
  }

  DeActiveLockout(model: IForgetPasswordModel): Observable<IResponseResult<unknown>> {

    return this.http
      .post<IResponseResult<unknown>>(this.DeActiveLockoutUrl, model, { responseType: 'json' });
  }

  public AdminForceActive(model: IAddRemoveRoleModel): Observable<IResponseResult<unknown>> {

    return this.http.post<IResponseResult<unknown>>(this.AdminForceActiveUrl, model, { responseType: 'json' });
  }

  public AdminForceDeActive(model: IAddRemoveRoleModel): Observable<IResponseResult<unknown>> {

    return this.http.post<IResponseResult<unknown>>(this.AdminForceDeActiveUrl, model, { responseType: 'json' });
  }

  // tslint:disable-next-line: typedef
  private showError(errorResponse: HttpErrorResponse) {

    AccountService.ErrorState = errorResponse.status;
    AccountService.ErrorMessage = errorResponse.error;

    return throwError('Error');
  }
}
