import { Injectable } from '@angular/core';
import {
  HttpRequest,
  HttpHandler,
  HttpEvent,
  HttpInterceptor
} from '@angular/common/http';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/Operators';
import { Router } from '@angular/router';
import { GAccount } from '../common/GAccount';
import { Urls } from '../common/Urls';
import { DomainName } from './PathTools';
import { SharedIonic } from '../common/SharedIonic';
import { ToastController, AlertController } from '@ionic/angular';
import { SiteLanguageService } from '../i18n/site-language.service';

@Injectable()
export class AccountInterceptor implements HttpInterceptor {

  constructor(private router: Router, public toastController: ToastController, public alertController: AlertController, private language: SiteLanguageService) { }

  async alert() {

    const alert = await this.alertController.create({
      cssClass: 'main-alert2',
      header: 'توجه',
      message: 'اکانت شما موقت قفل شده است',
      backdropDismiss: false,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }

  async alert2() {

    const alert = await this.alertController.create({
      cssClass: 'main-alert2',
      header: 'توجه',
      message: 'آی پی شما موقت بلوک شده است',
      backdropDismiss: false,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }

  intercept(request: HttpRequest<unknown>, next: HttpHandler): Observable<HttpEvent<unknown>> {
    const isRelativeApi = request.url.startsWith('/api/');
    if (!isRelativeApi && !request.url.startsWith(DomainName + '/api/')) {
      return next.handle(request);
    }

    const isPublicIp = request.url.split('?')[0].endsWith('/api/Site/GetPublicIp');
    const token = !isPublicIp && GAccount.IsLoggedIn() ? GAccount.TokenDecryptValue : null;
    let headers = request.headers.set('Accept-Language', this.language.current);
    if (token) {
      headers = headers.set('Authorization', 'Bearer ' + token);
    }
    const clonedReq = request.clone({ url: isRelativeApi ? DomainName + request.url : request.url, headers });

    return next.handle(clonedReq).pipe(tap({
      error: err => {
        if (err.status === 401) {
          // An endpoint's business error or an older request cannot delete the current session.
          if (token && err.error?.code === 'invalid_session' && token === GAccount.TokenDecryptValue) {
            GAccount.SignOut();
            this.router.navigateByUrl(this.language.url(Urls.AccountUrl));
          } else if (!token && !GAccount.IsLoggedIn()) {
            this.router.navigateByUrl(this.language.url(Urls.AccountUrl));
          }
        } else if (err.status === 0) {
          SharedIonic.toast(this.toastController, 'اینترنت قطع است');
        } else if (err.status === 500) {
          this.router.navigateByUrl(Urls.Page500Url);
        } else if (err.status === 423) {
          this.alert();
        } else if (err.status === 403) {
          this.alert2();
        }
      }
    }));
  }
}
