import { Injectable } from '@angular/core';
import { CanActivate, CanActivateChild, Router, UrlTree } from '@angular/router';
import { GAccount } from '../../common/GAccount';
import { Urls } from '../../common/Urls';

@Injectable({
  providedIn: 'root'
})
export class AdminOrSuperAdminGuard implements CanActivate, CanActivateChild {
  constructor(private router: Router) { }

  canActivate(): boolean | UrlTree {
    return this.canViewRestrictedPages();
  }

  canActivateChild(): boolean | UrlTree {
    return this.canViewRestrictedPages();
  }

  private canViewRestrictedPages(): boolean | UrlTree {
    return GAccount.IsAdminActive() || GAccount.IsSuperAdminActive()
      ? true
      : this.router.createUrlTree([Urls.HomeUrl]);
  }
}
